import logo from '/newreactsite/src/logo.svg';
import { Link, useLocation } from 'react-router-dom';
import { useSpring, animated } from '@react-spring/web';
import { Form } from './Forms';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faFacebook, faXTwitter, faInstagram } from '@fortawesome/free-brands-svg-icons';
import { faEnvelope, faLocationPin, faPhone, faShareNodes } from '@fortawesome/free-solid-svg-icons';
import { useAuth } from './user/auth/auth';

function Footer() {
    const auth = useAuth();
    const rotateInf = useSpring({
        from: {rotate: 0},
        to: {rotate: 360},
        loop: true,
        config: {duration: 20000},
    });
    const location = useLocation();
    const isVisible = location.pathname !== "/contact-us";
    const pathnames = location.pathname;
    return (
        <>
        {!auth.user ? null :
            <>
            {isVisible ? (<section className='contact-form-section mb-10'>
                <h2 className="text-center text-xl font-bold"><span>Contact </span>Us</h2>
                <Form/>
            </section>) : null}
            <section className='footer bg-[#282c34]'>
                <div className="container">
                    <div className='flex flex-wrap overflow-hidden'>
                        <div className='useful-lnks inline-flex flex-col flex-auto text-white mb-4 lg:m-4'>
                            <h2 className='text-lg font-bold'>Useful Links:</h2>
                            <ul>
                                <li className={'group select-none' + (pathnames === '/' ? ' pointer-events-none font-bold opacity-50' : '')}>
                                    <Link to="/" className='font-bold lg:text-lg lg:delay-100 lg:duration-300 lg:group-hover:text-black'>Home</Link>
                                </li>
                                <li className={'group select-none' + (pathnames === '/about' ? ' pointer-events-none font-bold opacity-50' : '')}>
                                    <Link to="/about" className='font-bold lg:text-lg lg:delay-100 lg:duration-300 lg:group-hover:text-black'>About</Link>
                                </li>
                                <li className={'group select-none' + (pathnames === '/gallery' ? ' pointer-events-none font-bold opacity-50' : '')}>
                                    <Link to="/gallery" className='font-bold lg:text-lg lg:delay-100 lg:duration-300 lg:group-hover:text-black'>Gallery</Link>
                                </li>
                                <li className={'group select-none' + (pathnames === '/testimonials' ? ' pointer-events-none font-bold opacity-50' : '')}>
                                    <Link to="/testimonials" className='font-bold lg:text-lg lg:delay-100 lg:duration-300 lg:group-hover:text-black'>Testimonials</Link>
                                </li>
                                <li className={'group select-none' + (pathnames === '/contact-us' ? ' pointer-events-none font-bold opacity-50' : '')}>
                                    <Link to="/contact-us" className='font-bold lg:text-lg lg:delay-100 lg:duration-300 lg:group-hover:text-black'>Contact Us</Link>
                                </li>
                            </ul>
                        </div>
                        <div className='comms inline-flex flex-col flex-auto text-white mb-4 lg:m-4'>
                            <h2 className='text-lg font-bold'>Communications:</h2>
                            <ul>
                                <li className='group select-none'>
                                    <Link to={'mailto:test@test.com'} className='font-bold lg:text-lg lg:delay-100 lg:duration-300 lg:group-hover:text-black'>
                                        <FontAwesomeIcon icon={faEnvelope} size='lg' className='mr-2'/>
                                    test@test.com</Link>
                                </li>
                                <li className='group select-none'>
                                    <Link to={'tel:0123456789'} className='font-bold lg:text-lg lg:delay-100 lg:duration-300 lg:group-hover:text-black'>
                                        <FontAwesomeIcon icon={faPhone} size='lg' className='mr-2'/>
                                    012 345 6789</Link>
                                </li>
                                <li className='group select-none'>
                                    <Link to={''} className='font-bold lg:text-lg lg:delay-100 lg:duration-300 lg:group-hover:text-black'>
                                        <FontAwesomeIcon icon={faLocationPin} size='lg' className='mr-2'/>
                                    0123 Test Building, Test Area<br/>Test City, Test State 012345</Link>
                                </li>
                            </ul>
                        </div>
                        <div className='loc inline-flex flex-col flex-auto justify-center text-white mb-4 lg:m-4'>
                            <iframe title='Google Maps iFrame' src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d5250.127653224991!2d2.2944809999999936!3d48.85837!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x47e66e2964e34e2d%3A0x8ddca9ee380ef7e0!2sEiffel%20Tower!5e0!3m2!1sen!2sus!4v1752179628401!5m2!1sen!2sus"></iframe>
                        </div>
                    </div>
                    <div id='logo' className='w-16 m-auto pt-4'>
                        <animated.img style={{...rotateInf}} src={logo} className="App-logo" alt="logo"></animated.img>
                    </div>
                    <div className='social max-w-[280px] flex justify-evenly py-4 m-auto'>
                        <span className='float-left text-white'>Follow us <FontAwesomeIcon icon={faShareNodes} size='xl'/></span>
                        <span className='border-r-2 border-white opacity-30'></span>
                        <ul className='flex justify-center gap-2 text-center'>
                            <li><Link to={'/'} className='text-white hover:text-slate-500' rel='nofollow noopener noreferrer' aria-label='Facebook page'><FontAwesomeIcon icon={faFacebook} size='xl'/></Link></li>
                            <li><Link to={'/'} className='text-white hover:text-slate-500' rel='nofollow noopener noreferrer' aria-label='Twitter page'><FontAwesomeIcon icon={faXTwitter} size='xl'/></Link></li>
                            <li><Link to={'/'} className='text-white hover:text-slate-500' rel='nofollow noopener noreferrer' aria-label='Instagram page'><FontAwesomeIcon icon={faInstagram} size='xl'/></Link></li>
                        </ul>
                    </div>
                </div>
            </section>
            </>
        }
        </>
    );
}

export default Footer;