// Scroll To Top button
const ScrollToTopButton = () => {
  const [isVisible, setIsVisible] = useState(false);

  // Show or hide the button based on scroll position
  const toggleVisibility = () => {
    if (window.scrollY > (window.innerHeight/1.99)) {
      setIsVisible(true);
    } else {
      setIsVisible(false);
    }
  };

  // Scroll to the top of the page
  const scrollToTop = (e) => {
    e.target.blur();
    window.scrollTo({
      top: 0,
      behavior: "smooth", // Smooth scroll behavior
    });
  };

  // Event listener for scroll
  useEffect(() => {
    window.addEventListener("scroll", toggleVisibility);

    // Cleanup event listener on unmount
    return () => {
      window.removeEventListener("scroll", toggleVisibility);
    };
  }, []);

  // React-Spring animation for fading the button
  const buttonAnimation = useSpring({
    //display: isVisible ? 'block' : 'none',
    transform: isVisible ? "translateX(0%)" : "translateX(120%)", // Add slight slide effect
    config: { tension: 300, friction: 30 },
  });

  return (
    <animated.button
      className={'scrollToTop fixed opacity-30 bottom-12 right-0 w-10 h-10 bg-[#008b8b] text-[#f0f3f5] uppercase font-bold border-0 shadow-[0_4px_6px_0_rgba(0,0,0,0.5)] pointer rounded-l-full text-sm z-10'}
      aria-label={'Scroll to top button'}
      onClick={scrollToTop}
      style={{
        ...buttonAnimation,
        transition: elastic,
      }}
    >
      <FontAwesomeIcon icon={faArrowUp}></FontAwesomeIcon>
    </animated.button>
  );
};

// APP //
function App() {
  useEffect(() => {
    const handleScroll = () => {
      if (window.scrollY > 100) {
        // Add class if scrolled past 100px
        document.body.classList.add("scrolled");
      } else {
        // Remove class if less than 100px
        document.body.classList.remove("scrolled");
      }
    };
  
    // Add scroll event listener
    window.addEventListener("scroll", handleScroll);
  
    // Cleanup the event listener on unmount
    return () => {
      window.removeEventListener("scroll", handleScroll);
    };
  }, []);
  return (
    <AuthProvider>
      <ScrollToTop/>
      <Header/>
      <PageWrapper/>
      <ScrollToTopButton/>
      <Routes>
        <Route path="/user/login" element={<Login/>}/>
        <Route path="/user/signup" element={<Signup/>}/>
        {/* Menu Route */}
        <Route exact path="/" element={
          <AuthRoute>
            <Home />
          </AuthRoute>} />
        <Route path="/about" element={
          <AuthRoute>
            <About />
          </AuthRoute>} />
        <Route path="/gallery" element={
          <AuthRoute>
            <Gallery />
          </AuthRoute>} />
        <Route path='/testimonials' element={
          <AuthRoute>
            <Testimonials />
          </AuthRoute>}/>
        <Route path="/contact-us" element={<ContactForm />} />
      </Routes>
      <div id='footer'>
        <Footer/>
      </div>
    </AuthProvider>
  );
};

const PageWrapper = () => {
  usePageClass();
  return null;
};

export default App;
