import { useEffect, useState, useRef } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faBars, faChevronDown, faXmark } from '@fortawesome/free-solid-svg-icons';
import '../js/scripts';
import { useSpring, animated } from '@react-spring/web';
import { useAuth } from './user/auth/auth';

const Menu = () => {
  const [isOpen, setIsOpen] = useState(false);
  const menuRef = useRef(null);
  const iconRef = useRef(null);
  const isMobile = window.innerWidth < 1024;
  const auth = useAuth();

  const onLogout = async () => {
    auth.logout();
    sessionStorage.clear();
  }

  const menuAnimation = useSpring({
    opacity: isMobile ? (isOpen ? 1 : 0) : '',
    maxHeight: isMobile ? (isOpen ? 500 : 0) : '',
    transform: isMobile ? (isOpen ? 'translateY(0%)' : 'translateY(-100%)') : '',
    overflow: isMobile ? (isOpen ? 'auto' : 'hidden') : 'auto',
    config: { tension: 300, friction: 30 },
  });

  useEffect(() => {
    const body = document.body;
    const menuElem = document.querySelector('.mobile-menu');

    if (isOpen && isMobile) {
      body.classList.add('menu-active');
      menuElem?.classList.add('menu-active');
    } else {
      body.classList.remove('menu-active');
      menuElem?.classList.remove('menu-active');
      document.querySelectorAll('li.parent').forEach(el => {
        el.classList.remove('active')
      });
    }
  },[isOpen]);

  useEffect(() => {
    const handleClickOut = (e) => {
      if (
        isOpen &&
        menuRef.current &&
        !menuRef.current.contains(e.target) &&
        iconRef.current &&
        !iconRef.current.contains(e.target)
      ) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOut);
    return () => document.addEventListener('mousedown', handleClickOut);
  },[isOpen]);

  const handleLinkClick = () => {
    setIsOpen(false);
  }

  const location = useLocation();
  const pathnames = location.pathname;
  const myAccount = location.pathname.startsWith('/my-account');

  return (
    <>
      {isMobile ? <div className='mobile-menu'><Link to='' ref={iconRef} onClick={(e) => { e.preventDefault(); setIsOpen(prev => !prev) }} className='text-5xl' aria-label='Menu'><FontAwesomeIcon icon={isOpen ? faXmark : faBars} /></Link></div> : null}
      <nav>
        <animated.ul ref={menuRef} style={menuAnimation} className='mainmenu w-full items-center absolute left-0 top-[90px] bg-slate-500 lg:flex lg:flex-wrap lg:justify-end lg:gap-y-3 lg:[position:unset] lg:bg-transparent'>
          <li className={'group px-2 select-none lg:float-left lg:delay-100 lg:duration-300 lg:hover:bg-[#f0f3f5] lg:rounded-full' + (pathnames === '/' ? ' pointer-events-none lg:bg-[#f0f3f5]' : '')}>
            <Link onClick={handleLinkClick} to="/" className={'px-3 font-bold lg:text-lg lg:p-0 lg:delay-100 lg:duration-300 lg:group-hover:text-black' + (pathnames === '/' ? ' lg:text-black lg:rounded-full' : '')}>Home</Link>
          </li>
          <li className={'group px-2 select-none lg:float-left lg:delay-100 lg:duration-300 lg:hover:bg-[#f0f3f5] lg:rounded-full' + (pathnames === '/about' ? ' pointer-events-none lg:bg-[#f0f3f5]' : '')}>
            <Link onClick={handleLinkClick} to="/about" className={'px-3 font-bold lg:text-lg lg:p-0 lg:delay-100 lg:duration-300 lg:group-hover:text-black' + (pathnames === '/about' ? ' lg:text-black' : '')}>About</Link>
          </li>
          <li className={'group px-2 select-none lg:float-left lg:delay-100 lg:duration-300 lg:hover:bg-[#f0f3f5] lg:rounded-full' + (pathnames === '/gallery' ? ' pointer-events-none lg:bg-[#f0f3f5]' : '')}>
            <Link onClick={handleLinkClick} to="/gallery" className={'px-3 font-bold lg:text-lg lg:p-0 lg:delay-100 lg:duration-300 lg:group-hover:text-black' + (pathnames === '/gallery' ? ' lg:text-black' : '')}>Gallery</Link>
          </li>
          <li className={'group px-2 select-none lg:float-left lg:delay-100 lg:duration-300 lg:hover:bg-[#f0f3f5] lg:rounded-full' + (pathnames === '/testimonials' ? ' pointer-events-none lg:bg-[#f0f3f5]' : '')}>
            <Link onClick={handleLinkClick} to="/testimonials" className={'px-3 font-bold lg:text-lg lg:p-0 lg:delay-100 lg:duration-300 lg:group-hover:text-black' + (pathnames === '/testimonials' ? ' lg:text-black' : '')}>Testimonials</Link>
          </li>
          <li className={'group px-2 select-none lg:float-left lg:delay-100 lg:duration-300 lg:hover:bg-[#f0f3f5] lg:rounded-full' + (pathnames === '/contact-us' ? ' pointer-events-none lg:bg-[#f0f3f5]' : '')}>
            <Link onClick={handleLinkClick} to="/contact-us" className={'px-3 font-bold lg:text-lg lg:p-0 lg:delay-100 lg:duration-300 lg:group-hover:text-black' + (pathnames === '/contact-us' ? ' lg:text-black' : '')}>Contact Us</Link>
          </li>
          <li className={'parent group px-2 lg:float-left lg:delay-300 lg:duration-300 lg:hover:bg-[#f0f3f5] lg:rounded-full' + (pathnames === '/my-account' ? ' lg:bg-[#f0f3f5]' : '')}>My Account<FontAwesomeIcon icon={faChevronDown} className={'lg:pl-1 lg:group-hover:text-black lg:duration-300 lg:delay-300' + (myAccount ? ' lg:text-black' : '')} />
            <ul style={{ display: isOpen ? 'none' : '' }} className='submenu max-w-[250px] m-auto text-center bg-[#272b36] border-t-4 border-slate-500 overflow-hidden max-lg:hidden lg:py-4 lg:opacity-0 lg:scale-y-0 lg:group-hover:opacity-[1] lg:group-hover:scale-y-[1] lg:origin-top lg:delay-300 lg:duration-300 lg:absolute lg:w-full lg:left-[unset] lg:right-1'>
              <li className={'parent group lg:py-2 lg:hover:bg-slate-500 lg:hover:text-black' + (myAccount ? ' bg-slate-500 lg:text-black' : '')}>
                <Link onClick={handleLinkClick && onLogout} to={'/#logout'} className='font-bold'>Logout</Link>
              </li>
            </ul>
          </li>
        </animated.ul>
      </nav>
    </>
  );
}

export default Menu;