import $ from 'jquery';
import SimpleParallax from "simple-parallax-js/vanilla";

$(document).ready(function() {

    //Start Mobile Menu
        $('nav > .mainmenu > li.parent, .user-account li.parent').addClass('parent-menu');

        if ((window.matchMedia("(max-width: 1023.98px)").matches)) {
            $('nav > .mainmenu > .parent-menu > svg').on('click', function() {
                var $parentMenu = $(this).parent('.parent-menu');

                $('.parent-menu').not($parentMenu).removeClass('active');

                $parentMenu.toggleClass('active');

                var $submenu = $parentMenu.children('.submenu');
                if ($submenu.length) {
                    $('.parent-menu > .submenu').not($submenu).slideUp('250');

                    $submenu.slideToggle('250');
                }
            });
        }
    //End Mobile Menu

    //body Parallax start
    const images = document.getElementsByClassName('thumbnail');
    new SimpleParallax(images, {
        delay: 30,
        scale: 5,
        customWrapper: '.bodyparallax',
    });
    //END
});