import { createContext, useContext, useEffect, useState } from "react";
import { useLocation } from "react-router-dom";

const AuthContext = createContext(null);

export const AuthProvider = ({children}) => {

    const [user, setUser] = useState(null);
    const location = useLocation();
    const pathnames = location.pathname;

    const login = (user) => {
        setUser(user);
    }

    const logout = () => {
        setUser(null);
    }

    const checkUser = async () => {
        const _id = sessionStorage.getItem("i");

        if (!_id) return;

        try {
            const res = await fetch('https://user-server-nzts.onrender.com/user/check-user', {
                method: 'POST',
                headers: {"Content-Type": "application/json"},
                body: JSON.stringify({_id: _id})
            });
            const result = await res.json();
            if (result.exists) {
                console.log("Match");
                setUser(result._id);
            } else {
                console.log("No match");
                setUser(null);
            }
        } catch (err) {
            console.log(err);
            setUser(null);
        }
    }

    useEffect(() => {
        let currentId = sessionStorage.getItem("i");

        const interval = setInterval(() => {
            const newId = sessionStorage.getItem("i");
            if (pathnames !== '/user/signup' && '/user/login') {
                if (newId !== currentId) {
                    currentId = newId;
                    checkUser();
                }
            }
        }, 1000);
        return () => clearInterval(interval);
    },[]);

    return (
        <AuthContext.Provider value={{user, login, logout, checkUser}}>
            {children}
        </AuthContext.Provider>
    )
}

export const useAuth = () => {
    return useContext(AuthContext);
}