import banner1 from '../components/images/banner1.webp';
import banner2 from '../components/images/banner2.webp';
import banner3 from '../components/images/banner3.webp';
import Slider from 'react-slick';
import 'slick-carousel/slick/slick.css';
import 'slick-carousel/slick/slick-theme.css';
import '../Carousel.css';
import {AboutContent} from './About';
import { GalleryContent } from './Gallery';
/* import { ProductCategoriesList } from './ProductCategories'; */
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {faCircleDot} from '@fortawesome/free-solid-svg-icons';
import { TestimonialsSlider } from './Testimonials';

const carouselcontent = [
    {
        id: 1,
        img: banner1,
        alt: "Banner 1",
        caption: <h2 className='text-center text-2xl font-medium uppercase'><span className='text-[#f0f3f5] invert-[100]'>Caption</span> for banner 1</h2>,

    },
    {
        id: 2,
        img: banner2,
        alt: "Banner 2",
        caption: <h2 className='text-center text-2xl font-medium uppercase'><span className='text-[#f0f3f5] invert-[100]'>Caption</span> for banner 2</h2>,

    },
    {
        id: 3,
        img: banner3,
        alt: "Banner 3",
        caption: <h2 className='text-center text-2xl font-medium uppercase'><span className='text-[#f0f3f5] invert-[100]'>Caption</span> for banner 3</h2>,

    }
];

export const Carousel = () => {
    const settings = {
        fade: true,
        cssEase: 'ease-in-out',
        dots: true,
        customPaging: i => (<FontAwesomeIcon icon={faCircleDot} color='lightgrey' size='xs'/>),
        infinite: true,
        speed: 300,
        slidesToShow: 1,
        slidesToScroll: 1,
        arrows: true,
        autoplay: true,
        pauseOnFocus: true,
        lazyLoad: 'ondemand',
        autoplaySpeed: 6000,
        responsive: [
            {
            breakpoint: 768,
            settings: {
                arrows: false
                }
            }
        ]
    };

    return (
        <section className="carousel-wrapper w-full bg-gray-900 relative overflow-hidden">
            {/* <SimpleParallax scale={2} transition={'ease'}>
                <img src={bannerpattern} alt='banner-pattern' />
            </SimpleParallax> */}
            <Slider className='homeBanner' {...settings}>
                {carouselcontent.map(({id, img, alt, caption}) => (
                <div key={id}>
                    <img
                        src={img}
                        alt={alt}
                        className='w-full h-[90vh] object-cover sm:h-[100vh] md:h-[calc(100vh-96px)] lg:h-[100vh] lg:object-top' loading="lazy"/>
                    <div className='caption absolute text-[#f9f9f9] top-0 w-full h-full'>
                        <div className='captiontext relative top-3/4 -translate-y-1/2 py-4'>
                            {caption}
                        </div>
                    </div>
                </div>
                ))}
            </Slider>
        </section>
    );
};

const Home = () => {
    return (
        <div id='main'>
            <Carousel/>
            {/* <section className='product-categories-section'>
                <h2 className='text-center text-2xl font-semibold'>Product Categories</h2>
                <ProductCategoriesList/>
            </section> */}
            <section className='about-section mb-10'>
                <AboutContent/>
            </section>
            <section className='testimonials-section mb-10'>
                <h2 className="text-center text-xl font-bold"><span>Case</span> Studies</h2>
                <TestimonialsSlider/>
            </section>
            <section className='gallery-section mb-10'>
                <h2 className="text-center text-xl font-bold"><span>Check Our </span>ins and outs</h2>
                <GalleryContent/>
            </section>
        </div>
    );
}

export default Home;